"use client";

import { useState, useMemo, useRef, useEffect, useId, memo, type ReactNode } from "react";
import { Search, Pin, ChevronDown, X, Sparkles } from "lucide-react";
import { motion } from "framer-motion";
import { cn } from "../lib/cn";
import { useAnchoredPosition } from "../lib/use-anchored-position";
import { useDismissOnOutside } from "../lib/hooks";

/** A horizontally-scrolling strip with an always-visible, drag-able scrollbar that
 *  works in EVERY browser — including iOS Safari, which renders neither
 *  `::-webkit-scrollbar` nor `scrollbar-width`. We hide the native bar and draw our
 *  own thumb synced to scrollLeft; native touch-swipe + trackpad scrolling still
 *  work, and the thumb is pointer-draggable for mouse users who can't wheel sideways. */
function HScrollRow({ children, className }: { children: ReactNode; className?: string }) {
    const scrollRef = useRef<HTMLDivElement>(null);
    const [thumb, setThumb] = useState({ w: 0, x: 0, show: false });

    const sync = () => {
        const el = scrollRef.current;
        if (!el) return;
        const { scrollWidth, clientWidth, scrollLeft } = el;
        const overflow = scrollWidth - clientWidth;
        if (overflow <= 1) {
            setThumb((t) => (t.show ? { w: 0, x: 0, show: false } : t));
            return;
        }
        const w = Math.max((clientWidth / scrollWidth) * clientWidth, 28);
        const x = (scrollLeft / overflow) * (clientWidth - w);
        setThumb({ w, x, show: true });
    };

    useEffect(() => {
        const el = scrollRef.current;
        if (!el) return;
        sync();
        el.addEventListener("scroll", sync, { passive: true });
        // Resync on width changes of the strip AND its content (chips added/removed).
        const ro = typeof ResizeObserver !== "undefined" ? new ResizeObserver(sync) : null;
        ro?.observe(el);
        if (el.firstElementChild) ro?.observe(el.firstElementChild);
        return () => {
            el.removeEventListener("scroll", sync);
            ro?.disconnect();
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const onThumbDown = (e: React.PointerEvent<HTMLDivElement>) => {
        const el = scrollRef.current;
        if (!el) return;
        e.preventDefault();
        e.currentTarget.setPointerCapture(e.pointerId);
        const startX = e.clientX;
        const startScroll = el.scrollLeft;
        const move = (ev: PointerEvent) => {
            const { scrollWidth, clientWidth } = el;
            const w = Math.max((clientWidth / scrollWidth) * clientWidth, 28);
            const travel = clientWidth - w;
            if (travel <= 0) return;
            el.scrollLeft = startScroll + ((ev.clientX - startX) / travel) * (scrollWidth - clientWidth);
        };
        const up = () => {
            window.removeEventListener("pointermove", move);
            window.removeEventListener("pointerup", up);
        };
        window.addEventListener("pointermove", move);
        window.addEventListener("pointerup", up);
    };

    return (
        <div className="relative">
            <div
                ref={scrollRef}
                className={cn(
                    "overflow-x-auto overflow-y-hidden overscroll-x-contain touch-pan-x [scrollbar-width:none] [-ms-overflow-style:none] [&::-webkit-scrollbar]:hidden",
                    className,
                )}
            >
                {children}
            </div>
            {thumb.show && (
                <div
                    onPointerDown={onThumbDown}
                    role="scrollbar"
                    aria-orientation="horizontal"
                    aria-hidden
                    className="absolute bottom-0 left-0 h-1.5 rounded-full bg-muted-foreground/40 hover:bg-muted-foreground/60 active:bg-muted-foreground/70 cursor-grab active:cursor-grabbing touch-none transition-colors"
                    style={{ width: `${thumb.w}px`, transform: `translateX(${thumb.x}px)` }}
                />
            )}
        </div>
    );
}

// =====================================================
// MODEL SELECT (generic, domain-agnostic)
// The searchable / grouped / filterable / pinnable model-picker MACHINERY,
// extracted so apps don't each re-implement it. The consumer maps its domain
// model to `ModelSelectOption` (supplying the per-row JSX as `icon`/`badges`/
// `detail`/`meta`), and owns pinning + capability filters via props. No i18n,
// no pricing, no app types live here.
// =====================================================

export interface ModelSelectOption {
    /** Stable id used as the value. */
    id: string;
    /** Display name (trigger label + primary search corpus). */
    label: string;
    /** Group key — models are grouped and provider-filtered by this. */
    group: string;
    /** Human label for the group (defaults to `group`). */
    groupLabel?: string;
    /** Extra text folded into search (ids, aliases, owner). */
    searchText?: string;
    /** Leading model icon (trigger + row). */
    icon?: ReactNode;
    /** Group/provider icon (filter chip + group header). */
    groupIcon?: ReactNode;
    /** Inline capability glyphs shown after the name. */
    badges?: ReactNode;
    /** Secondary line under the name (ids/aliases/pricing). */
    detail?: ReactNode;
    /** Right-aligned meta chip(s) (context length / max tokens). */
    meta?: ReactNode;
    disabled?: boolean;
}

/** A capability filter chip; `match` decides whether an option passes it. */
export interface ModelSelectFilter {
    key: string;
    /** Chip content (e.g. a capability badge). */
    node: ReactNode;
    title?: string;
    /** Whether an option satisfies this filter (all active filters must pass). */
    match: (option: ModelSelectOption) => boolean;
}

export interface ModelSelectLabels {
    placeholder?: string;
    search?: string;
    clearSearch?: string;
    clearFilters?: string;
    all?: string;
    pinned?: string;
    noResults?: string;
    pin?: string;
    unpin?: string;
}

export interface ModelSelectProps {
    options: ModelSelectOption[];
    /** Selected option id. */
    value: string;
    onChange: (id: string) => void;
    className?: string;
    labels?: ModelSelectLabels;
    /** Controlled pinned ids. Pass with `onTogglePin` to show the pin column. */
    pinned?: string[];
    onTogglePin?: (id: string) => void;
    /** Capability filter chips. */
    filters?: ModelSelectFilter[];
    /** Optional footer bar; receives the current (filtered) result count. */
    renderFooter?: (count: number) => ReactNode;
    /** Rendered at the very TOP of the open panel, above the search box — and always visible, even
     *  when the list is empty (unlike renderFooter, which hides on an empty result set). Use it for
     *  a domain toolbar that must stay reachable, e.g. a browse-mode switch above the picker. */
    renderHeader?: () => ReactNode;
    /** Bump this to imperatively clear the internal search + provider/capability filters WITHOUT
     *  remounting the panel (so it stays open and doesn't lose scroll/focus). Use it when the option
     *  set is swapped out from under the filters — e.g. toggling a browse mode — where a carried-over
     *  filter would otherwise empty the new list. */
    filterResetKey?: string | number;
}

/** A generic, searchable model picker: provider grouping + provider/capability
 *  filters + a pinned section + a styled dropdown. Domain-agnostic. */
export function ModelSelect({
    options,
    value,
    onChange,
    className,
    labels,
    pinned,
    onTogglePin,
    filters,
    renderFooter,
    renderHeader,
    filterResetKey,
}: ModelSelectProps) {
    const L = {
        placeholder: "Select a model",
        search: "Search models…",
        clearSearch: "Clear",
        clearFilters: "Clear filters",
        all: "All",
        pinned: "Pinned",
        noResults: "No models found",
        pin: "Pin",
        unpin: "Unpin",
        ...labels,
    };
    const [isOpen, setIsOpen] = useState(false);
    const instanceId = useId();
    const listboxId = `yunui-ms-${instanceId}-listbox`;
    const [search, setSearch] = useState("");
    const [activeGroup, setActiveGroup] = useState<string | null>(null);
    const [activeFilters, setActiveFilters] = useState<string[]>([]);
    // Clear search + provider/capability filters when the consumer bumps filterResetKey (e.g. a
    // browse-mode switch swapped the whole option set). Done as an effect, not a remount, so the
    // open panel keeps its position/focus and never flashes an empty "no results" from a stale filter.
    useEffect(() => {
        setSearch("");
        setActiveFilters([]);
        setActiveGroup(null);
    }, [filterResetKey]);
    const rootRef = useRef<HTMLDivElement>(null);
    const triggerRef = useRef<HTMLButtonElement>(null);
    useEffect(() => {
        if (!isOpen) return;
        const onEscape = (event: KeyboardEvent) => {
            if (event.key !== "Escape") return;
            event.preventDefault();
            event.stopPropagation();
            setIsOpen(false);
            requestAnimationFrame(() => triggerRef.current?.focus());
        };
        document.addEventListener("keydown", onEscape, true);
        return () => document.removeEventListener("keydown", onEscape, true);
    }, [isOpen]);
    const inputRef = useRef<HTMLInputElement>(null);
    const listRef = useRef<HTMLDivElement>(null);
    const panelRef = useRef<HTMLDivElement>(null);
    const pinFocusRef = useRef<{ id: string; source: HTMLButtonElement } | null>(null);
    useEffect(() => {
        const request = pinFocusRef.current;
        if (!request) return;
        if (!isOpen) { pinFocusRef.current = null; return; }
        if (request.source.isConnected) return;
        pinFocusRef.current = null;
        if (document.activeElement === document.body) {
            listRef.current?.querySelector<HTMLButtonElement>(`button[data-pin-id="${rowDomId(request.id)}"]`)?.focus();
        }
    }, [pinned, isOpen]);
    const togglePin = (id: string, source: HTMLButtonElement) => {
        pinFocusRef.current = document.activeElement === source ? { id, source } : null;
        onTogglePin?.(id);
    };
    // Keep the floating panel inside the viewport (the Radix dropdowns flip/shift
    // on their own; this hand-rolled one needs explicit collision handling).
    const { shift, maxHeight, placement } = useAnchoredPosition(isOpen, panelRef);
    const pinnedSet = useMemo(() => new Set(pinned ?? []), [pinned]);

    // Escape is handled separately below (it also restores focus to the trigger).
    useDismissOnOutside(isOpen, () => setIsOpen(false), rootRef, { escape: false });

    // On open: focus the search and bring the selected row into view.
    useEffect(() => {
        if (!isOpen) return;
        const t = setTimeout(() => {
            inputRef.current?.focus();
            if (value && listRef.current) {
                const el = listRef.current.querySelector<HTMLElement>(`[data-model-id="${CSS.escape(value)}"]`);
                // Do not centre a selection that is already visible. On compact
                // screens that needlessly moves the first row under the sticky
                // group header, leaving a clipped half-row at the top edge.
                el?.scrollIntoView({ block: "nearest" });
            }
        }, 50);
        return () => clearTimeout(t);
    }, [isOpen, value]);

    // Providers (groups) sorted by descending count.
    const groups = useMemo(() => {
        const counts: Record<string, number> = Object.create(null);
        for (const o of options) counts[o.group] = (counts[o.group] || 0) + 1;
        return Object.entries(counts).sort((a, b) => b[1] - a[1]).map(([g]) => g);
    }, [options]);
    const groupLabel = useMemo(() => {
        const m: Record<string, string> = Object.create(null);
        for (const o of options) if (o.groupLabel) m[o.group] = o.groupLabel;
        return m;
    }, [options]);
    const groupIcon = useMemo(() => {
        const m: Record<string, ReactNode> = Object.create(null);
        for (const o of options) if (o.groupIcon && !(o.group in m)) m[o.group] = o.groupIcon;
        return m;
    }, [options]);

    const filtered = useMemo(() => {
        const q = search.trim().toLowerCase();
        return options.filter((o) => {
            if (q) {
                const hay = `${o.label} ${o.searchText ?? ""} ${o.group}`.toLowerCase();
                if (!hay.includes(q)) return false;
            }
            if (activeGroup && o.group !== activeGroup) return false;
            if (activeFilters.length && filters) {
                const fs = filters.filter((f) => activeFilters.includes(f.key));
                if (!fs.every((f) => f.match(o))) return false;
            }
            return true;
        });
    }, [options, search, activeGroup, activeFilters, filters]);

    const pinnedList = useMemo(() => filtered.filter((o) => pinnedSet.has(o.id)), [filtered, pinnedSet]);
    const grouped = useMemo(() => {
        const acc: Record<string, ModelSelectOption[]> = Object.create(null);
        for (const o of filtered) {
            if (pinnedSet.has(o.id)) continue;
            (acc[o.group] ??= []).push(o);
        }
        return acc;
    }, [filtered, pinnedSet]);

    const selected = options.find((o) => o.id === value);

    const onWheel = (e: React.WheelEvent<HTMLDivElement>) => {
        const el = e.currentTarget;
        const atTop = el.scrollTop <= 1;
        const atBottom = el.scrollTop + el.clientHeight >= el.scrollHeight - 1;
        if ((atTop && e.deltaY < 0) || (atBottom && e.deltaY > 0)) e.preventDefault();
    };

    const closeAndRestoreFocus = () => {
        setIsOpen(false);
        requestAnimationFrame(() => triggerRef.current?.focus());
    };
    const panelMaxHeight = maxHeight == null
        ? "min(32rem, calc(100dvh - 7rem))"
        : `min(${maxHeight}px, 32rem, calc(100dvh - 7rem))`;

    // Keyboard navigation (combobox + listbox a11y): the search input keeps DOM
    // focus and drives a highlighted row via aria-activedescendant, so Arrow keys
    // move through results and Enter selects — without tabbing through every row.
    const flatOptions = useMemo(() => {
        const out: ModelSelectOption[] = [...pinnedList];
        for (const opts of Object.values(grouped)) out.push(...opts);
        return out;
    }, [pinnedList, grouped]);
    const enabledOptions = useMemo(() => flatOptions.filter((option) => !option.disabled), [flatOptions]);
    const select = (id: string) => {
        const option = options.find((item) => item.id === id);
        if (!option || option.disabled) return;
        onChange(id);
        closeAndRestoreFocus();
    };
    // -1 = no keyboard highlight yet. The ring only appears once the user
    // actually arrow-keys, so it never sits on the top row by default or fights
    // the mouse hover state.
    const [activeIndex, setActiveIndex] = useState(-1);
    // Reset the highlight whenever the visible set changes or the panel opens.
    useEffect(() => { setActiveIndex(-1); }, [isOpen, search, activeGroup, activeFilters, enabledOptions]);
    // Pointer use cedes the highlight back to hover (avoids a stuck ring +
    // hover fill showing at once).
    const clearActiveOnPointer = () => setActiveIndex((i) => (i === -1 ? i : -1));
    // Keep the highlighted row scrolled into view.
    useEffect(() => {
        const id = enabledOptions[activeIndex]?.id;
        if (!isOpen || !id || !listRef.current) return;
        listRef.current
            .querySelector<HTMLElement>(`[data-model-id="${CSS.escape(id)}"]`)
            ?.scrollIntoView({ block: "nearest" });
    }, [activeIndex, isOpen, enabledOptions]);
    const activeId = enabledOptions[activeIndex]?.id;
    const rowDomId = (id: string) => `yunui-ms-${instanceId}-opt-${Array.from(id, char => char.codePointAt(0)!.toString(16)).join("-")}`;
    const onSearchKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.key === "ArrowDown") {
            e.preventDefault();
            setActiveIndex((i) => Math.min(i + 1, enabledOptions.length - 1));
        } else if (e.key === "ArrowUp") {
            e.preventDefault();
            // From "no selection" (-1), Up jumps to the last row.
            setActiveIndex((i) => (i < 0 ? enabledOptions.length - 1 : Math.max(i - 1, 0)));
        } else if (e.key === "Enter") {
            e.preventDefault();
            // No row highlighted yet → Enter takes the top result (classic combobox).
            const o = enabledOptions[activeIndex] ?? enabledOptions[0];
            if (o) select(o.id);
        } else if (e.key === "Escape") {
            e.preventDefault();
            closeAndRestoreFocus();
        }
    };

    return (
        // Fixed-width root so the trigger doesn't grow/shrink as the selected
        // label changes; override the width via `className`.
        <div ref={rootRef} className={cn("relative w-64", className)}>
            <button
                ref={triggerRef}
                type="button"
                onClick={() => setIsOpen((o) => !o)}
                aria-expanded={isOpen}
                aria-haspopup="listbox"
                aria-controls={isOpen ? listboxId : undefined}
                className={cn(
                    "flex items-center gap-2 px-3 py-2 bg-card border border-border rounded-xl text-left group transition-all w-full shadow-sm hover:shadow-md outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
                    isOpen ? "border-ring/60 ring-2 ring-ring/25" : "border-border hover:border-ring",
                )}
            >
                {selected ? (
                    <>
                        {selected.icon}
                        <span className="flex-1 truncate text-sm font-medium">{selected.label}</span>
                    </>
                ) : (
                    <span className="flex-1 text-sm text-muted-foreground">{L.placeholder}</span>
                )}
                <ChevronDown size={14} className={cn("text-muted-foreground transition-transform shrink-0", isOpen && "rotate-180")} />
            </button>

            {isOpen && (
                    <motion.div
                        ref={panelRef}
                        /* motion.div WITHOUT AnimatePresence: a reliable enter
                           animation on mount, and an immediate unmount on close
                           (no exit delay → close is synchronous). Fixed width so
                           the panel never reflows as you search/filter. */
                        initial={{ opacity: 0, y: -8, scale: 0.96 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        transition={{ duration: 0.16, ease: "easeOut" }}
                        /* w-96 (= 24rem) is a CORE utility — always generated, so the
                           panel can't fall back to a full-bleed width the way an
                           arbitrary `w-[24rem]` did when the consuming app's JIT scan
                           missed it. The small-screen cap is an inline style (not an
                           arbitrary class) so it can't silently fail to generate.
                           `marginLeft`/`maxHeight` come from useAnchoredPosition so
                           the panel never spills off the right/bottom of the screen —
                           margin (not transform) so it doesn't fight the open
                           animation; height paired with the flex-1 scroll list below. */
                        data-yunui="model-select-panel"
                        style={{ maxWidth: "calc(100vw - 1rem)", marginLeft: shift, maxHeight: panelMaxHeight }}
                        className={`absolute z-50 left-0 ${placement === "top" ? "bottom-full mb-2 origin-bottom" : "top-full mt-2 origin-top"} w-96 max-w-[calc(100vw-1rem)] flex flex-col bg-popover border border-border rounded-2xl shadow-lg shadow-black/5 text-popover-foreground overflow-hidden`}
                    >
                        {/* Consumer header (e.g. a browse-mode switch) — pinned to the top of the
                            panel, always visible even when the list below is empty. */}
                        {renderHeader && (
                            <div className="p-2.5 border-b border-border/50">{renderHeader()}</div>
                        )}

                        {/* Search + capability filters */}
                        <div className="p-2.5 border-b border-border/50">
                            <div className="relative">
                                <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground pointer-events-none" />
                                <input
                                    ref={inputRef}
                                    value={search}
                                    onChange={(e) => setSearch(e.target.value)}
                                    onKeyDown={onSearchKeyDown}
                                    placeholder={L.search}
                                    aria-label={L.search}
                                    role="combobox"
                                    aria-expanded={isOpen}
                                    aria-controls={listboxId}
                                    aria-activedescendant={activeId != null ? rowDomId(activeId) : undefined}
                                    // 16px on mobile: iOS Safari zooms the whole page when a focused input
                                    // is under 16px, and this one opens inside a dropdown, so the zoom
                                    // lands mid-interaction.
                                    className="w-full pl-9 pr-8 py-2 text-base md:text-sm bg-muted/50 border border-transparent rounded-xl outline-none focus:border-ring focus:bg-background transition-colors"
                                />
                                {search && (
                                    <button type="button" onClick={() => setSearch("")} title={L.clearSearch} aria-label={L.clearSearch} className="absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors p-0.5 min-w-6 min-h-6 inline-flex items-center justify-center rounded-md hover:bg-muted outline-none focus-visible:ring-2 focus-visible:ring-ring">
                                        <X size={13} />
                                    </button>
                                )}
                            </div>
                            {filters && filters.length > 0 && (
                                <HScrollRow className="mt-2">
                                    <div className="flex items-center gap-1 px-2.5 pb-2 w-max">
                                        {filters.map((f) => {
                                            const on = activeFilters.includes(f.key);
                                            return (
                                                <button key={f.key} type="button" title={f.title} aria-label={f.title} aria-pressed={on} onClick={() => setActiveFilters((p) => (p.includes(f.key) ? p.filter((k) => k !== f.key) : [...p, f.key]))} className={cn("shrink-0 p-1 rounded-md transition-colors outline-none focus-visible:ring-2 focus-visible:ring-ring", on ? "bg-foreground/10" : "hover:bg-muted")}>
                                                    {f.node}
                                                </button>
                                            );
                                        })}
                                        {activeFilters.length > 0 && (
                                            <button type="button" onClick={() => setActiveFilters([])} title={L.clearFilters} aria-label={L.clearFilters} className="shrink-0 p-1 min-w-6 min-h-6 inline-flex items-center justify-center rounded-md text-muted-foreground hover:bg-muted outline-none focus-visible:ring-2 focus-visible:ring-ring">
                                                <X size={14} />
                                            </button>
                                        )}
                                    </div>
                                </HScrollRow>
                            )}
                        </div>

                        {/* Provider filter */}
                        {groups.length > 1 && (
                            <div className="border-b border-border/50">
                                <HScrollRow>
                                    <div className="flex gap-1 px-2.5 pt-2 pb-2.5 w-max">
                                        <button type="button" onClick={() => setActiveGroup(null)} aria-pressed={!activeGroup} className={cn("px-2.5 py-1.5 text-xs rounded-lg font-medium transition-colors whitespace-nowrap outline-none focus-visible:ring-2 focus-visible:ring-ring", !activeGroup ? "bg-foreground text-background" : "bg-muted text-(--text-secondary) hover:bg-muted/80")}>
                                            {L.all} ({options.length})
                                        </button>
                                        {groups.map((g) => (
                                            <button key={g} type="button" onClick={() => setActiveGroup((c) => (c === g ? null : g))} aria-pressed={activeGroup === g} className={cn("px-2.5 py-1.5 text-xs rounded-lg font-medium transition-colors flex items-center gap-1.5 whitespace-nowrap outline-none focus-visible:ring-2 focus-visible:ring-ring", activeGroup === g ? "bg-foreground text-background" : "bg-muted text-(--text-secondary) hover:bg-muted/80")}>
                                                <span aria-hidden="true" className="inline-flex">{groupIcon[g]}</span>
                                                {groupLabel[g] ?? g}
                                            </button>
                                        ))}
                                    </div>
                                </HScrollRow>
                            </div>
                        )}

                        {/* List */}
                        <div ref={listRef} onWheel={onWheel} onMouseMove={clearActiveOnPointer} className="flex-1 min-h-0 max-h-96 overflow-y-auto overscroll-contain">
                            {/* The accessible listbox owns only option nodes. Pin buttons
                                remain outside that composite, although the visual rows share
                                one scroll container. This preserves the existing appearance. */}
                            <div id={listboxId} role="listbox" aria-label={L.placeholder} aria-owns={flatOptions.length ? flatOptions.map(option => rowDomId(option.id)).join(" ") : `${listboxId}-empty`} />
                            {pinnedList.length > 0 && (
                                <div role="presentation" className="px-1.5 py-1.5 border-b border-border/40">
                                    <div aria-hidden="true" className="text-[10px] font-medium text-(--text-secondary) uppercase tracking-wide px-2 mb-1 flex items-center gap-1">
                                        <Pin size={9} /> {L.pinned}
                                    </div>
                                    {pinnedList.map((o) => (
                                        <ModelRow key={o.id} domId={rowDomId(o.id)} active={o.id === activeId} option={o} selected={o.id === value} pinned isPinnable={!!onTogglePin} pinLabel={L.pin} unpinLabel={L.unpin} pinnedLabel={L.pinned} onSelect={() => select(o.id)} onTogglePin={(source) => togglePin(o.id, source)} />
                                    ))}
                                </div>
                            )}
                            <div role="presentation" className="px-1.5 py-1.5">
                                {Object.entries(grouped).map(([g, opts]) => (
                                    <div key={g} role="presentation" className="mb-3 last:mb-0">
                                        {/* Sticky group header styled as a rounded bar that echoes the
                                            model rows (rounded-xl, same gutter) — a deliberate on-brand
                                            label, not a square full-bleed band. SOLID muted fill (no
                                            backdrop-blur): a per-header blur layer stacked on the panel's
                                            blur was 5 backdrop-filters deep, which makes hover/scroll
                                            stutter (esp. Safari). The solid fill occludes rows on its own. */}
                                        <div aria-hidden="true" className="sticky top-0 z-10 pt-1 pb-1.5">
                                            <div className="flex items-center gap-2 rounded-xl bg-muted px-3 py-2">
                                                {groupIcon[g]}
                                                <span className="text-xs font-semibold text-(--text-secondary)">{groupLabel[g] ?? g}</span>
                                                <span className="ml-auto shrink-0 min-w-5 text-center text-[10px] font-semibold tabular-nums text-(--text-secondary) bg-foreground/10 px-1.5 py-0.5 rounded-md">{opts.length}</span>
                                            </div>
                                        </div>
                                        {opts.map((o) => (
                                            <ModelRow key={o.id} domId={rowDomId(o.id)} active={o.id === activeId} option={o} selected={o.id === value} pinned={false} isPinnable={!!onTogglePin} pinLabel={L.pin} unpinLabel={L.unpin} pinnedLabel={L.pinned} onSelect={() => select(o.id)} onTogglePin={(source) => togglePin(o.id, source)} />
                                        ))}
                                    </div>
                                ))}
                            </div>
                            {filtered.length === 0 && (
                                <div id={`${listboxId}-empty`} role="option" aria-disabled="true" aria-selected="false" className="py-12 text-center text-muted-foreground">
                                    <Sparkles size={28} className="mx-auto mb-3 opacity-40" />
                                    <p className="text-sm">{L.noResults}</p>
                                </div>
                            )}
                        </div>

                        {renderFooter && filtered.length > 0 && (
                            <div className="border-t border-border/50 px-3 py-2 bg-muted/30 text-xs text-(--text-secondary)">
                                {renderFooter(filtered.length)}
                            </div>
                        )}
                    </motion.div>
                )}
        </div>
    );
}

const ModelRow = memo(function ModelRow({
    option,
    selected,
    active,
    domId,
    pinned,
    isPinnable,
    onSelect,
    onTogglePin,
    pinLabel,
    unpinLabel,
    pinnedLabel,
}: {
    option: ModelSelectOption;
    selected: boolean;
    /** Keyboard-highlighted row (aria-activedescendant target). */
    active?: boolean;
    domId?: string;
    pinned: boolean;
    isPinnable: boolean;
    onSelect: () => void;
    onTogglePin: (source: HTMLButtonElement) => void;
    pinLabel: string;
    unpinLabel: string;
    pinnedLabel: string;
}) {
    return (
        <div
            data-model-id={option.id}
            role="presentation"
            onClick={option.disabled ? undefined : onSelect}
            className={cn(
                "relative flex items-center gap-3 px-3 py-2.5 rounded-xl cursor-pointer group transition-colors",
                // A clear gray fill on both states (selected solid, hover lighter)
                // — the bar's opacity then tells selected from merely-hovered.
                selected ? "bg-muted" : "hover:bg-muted",
                // keyboard highlight (arrow-key navigation)
                active && "bg-muted ring-2 ring-ring/40",
            )}
        >
            <div
                id={domId}
                role="option"
                aria-selected={selected}
                aria-description={`${pinned ? `${pinnedLabel}, ` : ""}${option.groupLabel ?? option.group}`}
                aria-disabled={option.disabled || undefined}
                className="flex flex-1 min-w-0 items-center gap-3 self-stretch"
            >
            {/* Left bar — YunUI's selection signature, mirroring the Sidebar nav
                item: a faint full-height bar slides in on hover, and a solid bar
                marks the selected row. */}
            <div
                // 5px inset (Tailwind's 1.25 step isn't core; inline keeps it from
                // being dropped by a consumer's JIT scan of dist).
                style={{ left: "5px" }}
                className={cn(
                    "absolute top-1/2 w-1 h-6 rounded-full bg-primary transition-all duration-150 -translate-y-1/2",
                    selected
                        ? "opacity-100 translate-x-0"
                        : "opacity-0 -translate-x-1.5 group-hover:opacity-50 group-hover:translate-x-0",
                )}
            />
            {option.icon}
            <div className="flex-1 min-w-0">
                <div className="flex items-center gap-1.5">
                    <span className="font-medium truncate">{option.label}</span>
                    {option.badges}
                </div>
                {option.detail}
            </div>
            {option.meta && <div className="flex items-center gap-1 shrink-0">{option.meta}</div>}
            </div>
            {isPinnable && (
                <button
                    type="button"
                    data-pin-id={domId}
                    aria-pressed={pinned}
                    aria-describedby={domId}
                    onClick={(e) => { e.stopPropagation(); onTogglePin(e.currentTarget); }}
                    className={cn(
                        "p-1.5 rounded-md transition-all shrink-0 lg:opacity-0 lg:group-hover:opacity-100 lg:focus-visible:opacity-100 outline-none focus-visible:ring-2 focus-visible:ring-ring",
                        pinned ? "text-foreground opacity-100 hover:bg-muted/50" : "text-(--text-secondary) hover:text-foreground hover:bg-muted/50",
                    )}
                    aria-label={pinned ? unpinLabel : pinLabel}
                >
                    <Pin size={14} className={pinned ? "fill-current" : ""} />
                </button>
            )}
        </div>
    );
});

export default ModelSelect;
